package android.view;
import java.util.*;public class View {public static final int VISIBLE=0,GONE=8;final android.content.Context context;public int visibility;public boolean enabled=true,shown=true,attached=true;public boolean isShown(){return shown&&visibility==VISIBLE;}public boolean isAttachedToWindow(){return attached;}Map<Integer,View> children=new HashMap<Integer,View>();public View(android.content.Context c){context=c;}public void add(String name,View v){children.put(name.hashCode(),v);}public android.content.Context getContext(){return context;}public android.content.res.Resources getResources(){return context.getResources();}public View findViewById(int id){return children.get(id);}public void setVisibility(int v){visibility=v;}public void setEnabled(boolean b){enabled=b;}}
